import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.DNWyyI0w.js";const u=JSON.parse('{"title":"The Run Object","description":"","frontmatter":{},"headers":[],"relativePath":"reference/run-object.md","filePath":"reference/run-object.md"}'),r={name:"reference/run-object.md"};function c(n,t,i,s,h,l){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="the-run-object" tabindex="-1">The Run Object <a class="header-anchor" href="#the-run-object" aria-label="Permalink to &quot;The Run Object&quot;">​</a></h1><p>Field reference for <code>Run</code>. Optional fields are marked <code>?</code>; absent generally means <em>inherit</em> or <em>legacy record</em>, not <em>empty</em>.</p><h2 id="identity-ownership" tabindex="-1">Identity &amp; ownership <a class="header-anchor" href="#identity-ownership" aria-label="Permalink to &quot;Identity &amp; ownership&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>Run id</td></tr><tr><td><code>orgId?</code></td><td><code>string</code></td><td>Owning org (absent on legacy local records = <code>local</code>)</td></tr><tr><td><code>createdBy?</code></td><td><code>string</code></td><td>The member who started it. Budgets, permissions, and connections resolve against this user for every turn</td></tr><tr><td><code>createdByName?</code> / <code>createdByEmail?</code></td><td><code>string</code></td><td>Creator&#39;s display identity, stamped at creation</td></tr><tr><td><code>sharedWith?</code></td><td><code>string[]</code></td><td>Members invited to view. Viewers watch; they do not steer</td></tr><tr><td><code>title</code></td><td><code>string</code></td><td>Short human title, derived from the brief</td></tr><tr><td><code>brief</code></td><td><code>string</code></td><td>The original brief</td></tr></tbody></table><h2 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to &quot;State&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>status</code></td><td><code>RunStatus</code></td><td><code>active</code> | <code>awaiting_input</code> | <code>paused</code> | <code>done</code> | <code>error</code> | <code>cancelled</code></td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td><code>number</code></td><td>Epoch ms</td></tr><tr><td><code>attention?</code></td><td><code>RunAttention</code></td><td>Latest attention-worthy transition; its <code>id</code> changes only on entering a new such state, so reconnecting clients de-duplicate without losing it</td></tr><tr><td><code>lastResult?</code></td><td><code>string</code></td><td>Latest committed summary (preview source)</td></tr><tr><td><code>lastActivity?</code></td><td><code>string</code></td><td>Most recent live status line (best-effort)</td></tr></tbody></table><h2 id="target-execution" tabindex="-1">Target &amp; execution <a class="header-anchor" href="#target-execution" aria-label="Permalink to &quot;Target &amp; execution&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>project?</code></td><td><code>string</code></td><td>Primary project (coding runs)</td></tr><tr><td><code>branch?</code></td><td><code>string</code></td><td>Primary working branch</td></tr><tr><td><code>executionMode?</code></td><td><code>&#39;guided&#39; | &#39;autonomous&#39;</code></td><td>Who drives the dispatch loop. Absent = legacy autonomous</td></tr><tr><td><code>effortMode?</code></td><td><code>EffortMode</code></td><td>Stamped at creation; drives the model/reasoning preset</td></tr><tr><td><code>providerProfile?</code> / <code>model?</code></td><td><code>string</code></td><td>Run-wide overrides; <code>&#39;&#39;</code>/absent = inherit</td></tr><tr><td><code>agentConfigs?</code></td><td><code>Record&lt;string, RunAgentConfig&gt;</code></td><td>Per-actor overrides, keyed by <code>&#39;PRIME&#39;</code>, a project, or an agent. The most-specific layer</td></tr><tr><td><code>version?</code></td><td><code>string</code></td><td>The orchestrator build that <strong>started</strong> the run. Stamped once, never updated</td></tr></tbody></table><h2 id="plan" tabindex="-1">Plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;Plan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>checklist?</code></td><td><code>ChecklistItem[]</code></td><td>The live plan</td></tr><tr><td><code>originalChecklist?</code></td><td><code>ChecklistItem[]</code></td><td>The plan exactly as first frozen — makes drift visible</td></tr><tr><td><code>planVersion?</code></td><td><code>number</code></td><td><code>1</code> = set once, never amended</td></tr><tr><td><code>planApproval?</code></td><td><code>PlanApproval</code></td><td>Operator sign-off on the plan (not the work)</td></tr><tr><td><code>playbookId?</code></td><td><code>string</code></td><td>Set when the plan was replayed from a playbook rather than re-derived</td></tr><tr><td><code>appliedMemories?</code></td><td><code>AppliedMemory[]</code></td><td>Memory selected before planning and held stable</td></tr></tbody></table><h2 id="participants-sessions" tabindex="-1">Participants &amp; sessions <a class="header-anchor" href="#participants-sessions" aria-label="Permalink to &quot;Participants &amp; sessions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>participants</code></td><td><code>RunParticipant[]</code></td><td>Every agent that has taken part, PRIME included</td></tr><tr><td><code>primeSessionId?</code></td><td><code>string</code></td><td>PRIME&#39;s session for this run, separate from the main chat</td></tr><tr><td><code>primeNeedsRehydrate?</code></td><td><code>boolean</code></td><td>PRIME was compacted and not re-briefed. While set, the live-state block carries the <strong>full</strong> plan; the engine clears it once sent</td></tr></tbody></table><h2 id="in-flight" tabindex="-1">In-flight <a class="header-anchor" href="#in-flight" aria-label="Permalink to &quot;In-flight&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>inFlights?</code></td><td><code>RunInFlight[]</code></td><td>Every executing delegation, durable across a crash</td></tr><tr><td><code>inFlight?</code></td><td><code>RunInFlight</code></td><td>Legacy single-flight field, read only for backward-compatible recovery</td></tr><tr><td><code>pendingApproval?</code></td><td><code>PendingApproval</code></td><td>Present iff parked at an approval gate</td></tr></tbody></table><h2 id="thread-accounting" tabindex="-1">Thread &amp; accounting <a class="header-anchor" href="#thread-accounting" aria-label="Permalink to &quot;Thread &amp; accounting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>thread</code></td><td><code>RunEvent[]</code></td><td>The ordered shared conversation</td></tr><tr><td><code>usageLog?</code></td><td><code>RunUsageEntry[]</code></td><td>One entry per settled LLM call</td></tr><tr><td><code>verificationLog?</code></td><td><code>TaskVerificationRecord[]</code></td><td>Every gate verdict, append-only, run-level</td></tr><tr><td><code>optimizationReport?</code></td><td><code>RunOptimizationReport</code></td><td>First-pass count, retries, failure kinds, cost, max context</td></tr><tr><td><code>optimizationMode?</code></td><td><code>&#39;off&#39; | &#39;shadow&#39; | &#39;canary&#39; | &#39;on&#39;</code></td><td>Rollout state, stamped at creation so a result is attributable</td></tr></tbody></table><h2 id="runevent" tabindex="-1"><code>RunEvent</code> <a class="header-anchor" href="#runevent" aria-label="Permalink to &quot;`RunEvent`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>actor</code></td><td><code>OPERATOR</code> | <code>PRIME</code> | a project/agent name | <code>SYSTEM</code></td></tr><tr><td><code>kind</code></td><td><code>message</code> | <code>delegation</code> | <code>question</code> | <code>answer</code> | <code>tool</code> | <code>result</code> | <code>system</code></td></tr><tr><td><code>to?</code></td><td>Directed-at target (e.g. PRIME delegates <code>to: &quot;my-app&quot;</code>)</td></tr><tr><td><code>text</code> / <code>detail?</code></td><td>The message, and the full tool call/output for the expandable row</td></tr><tr><td><code>byUser?</code></td><td>For an <code>OPERATOR</code> event: which member sent or decided it</td></tr><tr><td><code>stats?</code></td><td>This message&#39;s own token/cost vitals</td></tr></tbody></table><h2 id="runeventstats" tabindex="-1"><code>RunEventStats</code> <a class="header-anchor" href="#runeventstats" aria-label="Permalink to &quot;`RunEventStats`&quot;">​</a></h2><p><code>inputTokens</code>, <code>outputTokens</code>, <code>cacheReadTokens?</code>, <code>cacheCreationTokens?</code>, <code>ms?</code>, <code>contextTokens?</code>, <code>costUsd?</code>, <code>model?</code>, and <code>costShared?</code> — the last meaning the cost is this message&#39;s <em>share</em> of a turn total rather than a provider-quoted per-call price.</p><h2 id="runsummary" tabindex="-1"><code>RunSummary</code> <a class="header-anchor" href="#runsummary" aria-label="Permalink to &quot;`RunSummary`&quot;">​</a></h2><p>The compact list view: the same identity, status, and plan fields without the full <code>thread</code>, plus <code>participants</code> (keys only), <code>participantContexts</code>, <code>preview</code>, <code>attachments</code>, and the live <code>inFlights</code>.</p><p>See also: <a href="/docs/concepts/runs">Runs</a> · <a href="/docs/concepts/plans-and-tasks">Plans &amp; Tasks</a></p>',23)])])}const m=e(r,[["render",c]]);export{u as __pageData,m as default};
